  if (version === 1 || layer !== 1) return null;
  const bitrate = L3_BITRATES[version === 3 ? 1 : 2][(bytes[offset + 2] >> 4) & 0xf];
  const sampleRate = SAMPLE_RATES[version]?.[(bytes[offset + 2] >> 2) & 3];
